"""UIFlow2 boot management. Embedded in the web installer, not written as boot.py."""
import os,json,hashlib,binascii
BASE='/flash'
MARKER='# STICK_VARIO_LAUNCHER_V1'
LAUNCHER='''# STICK_VARIO_LAUNCHER_V1
# Generated by Stick Vario installer. Keep UIFlow boot.py unchanged.
import M5,time,esp32
M5.begin()
_sv_recover=False
_sv_until=time.ticks_add(time.ticks_ms(),250)
while time.ticks_diff(_sv_until,time.ticks_ms())>0:
 M5.update()
 if M5.BtnB.isPressed():
  _sv_recover=True
  break
 time.sleep_ms(10)
if _sv_recover:
 _sv_nvs=esp32.NVS('uiflow')
 _sv_nvs.set_u8('boot_option',1)
 _sv_nvs.commit()
 print('I,BOOT_RECOVERY,UIFlow_menu')
 import machine
 machine.reset()
else:
 try:
  with open('/flash/stick_vario_app.py') as _sv_app_file:
   _sv_app_code=_sv_app_file.read()
  exec(_sv_app_code,globals())
 except KeyboardInterrupt:
  raise
 except Exception as _sv_error:
  print('E,AUTORUN',_sv_error)
  _sv_nvs=esp32.NVS('uiflow')
  _sv_nvs.set_u8('boot_option',1)
  _sv_nvs.commit()
  print('I,BOOT_RECOVERY,next_boot_UIFlow_menu')
'''

def _exists(path):
    try:os.stat(path);return True
    except OSError as e:
        if e.args[0]!=2:raise
        return False
def _hash(path):
    h=hashlib.sha256()
    with open(path,'rb') as f:
        while True:
            data=f.read(1024)
            if not data:break
            h.update(data)
    return binascii.hexlify(h.digest()).decode()
def _copy(src,dest):
    with open(src,'rb') as a,open(dest,'wb') as b:
        while True:
            data=a.read(1024)
            if not data:break
            b.write(data)
def _replace(temp,target):getattr(os,'replace',os.rename)(temp,target)
def _owned(path):
    if not _exists(path):return False
    with open(path) as f:return f.readline().strip()==MARKER
def _nvs():
    import esp32
    return esp32.NVS('uiflow')
def _mode(nvs):
    try:return nvs.get_u8('boot_option')
    except OSError:return None
def _set(nvs,mode):
    nvs.set_u8('boot_option',mode);nvs.commit()
def sv_boot(action='read',value=None):
    nvs=_nvs();main=BASE+'/main.py';app=BASE+'/stick_vario_app.py'
    backup=BASE+'/stick_vario_main_before_autorun.py';state_path=BASE+'/stick_vario_boot_state_v1.json'
    if action=='enable':
        if not _exists(app):raise ValueError('Installare prima stick_vario_app.py')
        owned=_owned(main)
        if _exists(BASE+'/main_ota_temp.py'):raise ValueError('Aggiornamento UIFlow pendente: completarlo prima di installare avvio automatico')
        if not owned:
            if _exists(state_path):
                with open(state_path) as f:state=json.load(f)
                if state.get('v')!=1 or type(state.get('had_main'))!=bool:raise ValueError('Metadati avvio non validi')
                matches=not state['had_main'] and not _exists(main)
                if state['had_main'] and _exists(main) and _exists(backup):
                    matches=_hash(main)==state.get('backup_sha256')==_hash(backup)
                if not matches:raise ValueError('Stato avvio precedente presente e main diverso: non sovrascrivo')
            else:
                had_main=_exists(main)
                state={'v':1,'boot_option':_mode(nvs),'had_main':had_main,'backup_sha256':None}
                if had_main:
                    if _exists(backup):
                        if _hash(backup)!=_hash(main):raise ValueError('Backup main diverso gia presente: non sovrascrivo')
                    else:
                        _copy(main,backup+'.new')
                        if _hash(main)!=_hash(backup+'.new'):raise ValueError('Backup main non valido')
                        _replace(backup+'.new',backup)
                    state['backup_sha256']=_hash(backup)
                with open(state_path+'.new','w') as f:f.write(json.dumps(state))
                _replace(state_path+'.new',state_path)
        elif not _exists(state_path):raise ValueError('Launcher senza metadati di ripristino')
        with open(main+'.new','w') as f:f.write(LAUNCHER)
        with open(main+'.new') as f:compile(f.read(),'main.py','exec')
        _replace(main+'.new',main)
        _set(nvs,0)
    elif action=='mode':
        if type(value)!=int or value not in (0,1,2):raise ValueError('Modalita UIFlow non valida')
        if value==0 and not _exists(main):raise ValueError('main.py assente')
        _set(nvs,value)
    elif action=='restore':
        if not _owned(main):raise ValueError('main.py non e il nostro launcher: non lo modifico')
        with open(state_path) as f:state=json.load(f)
        if state.get('v')!=1 or type(state.get('had_main'))!=bool:raise ValueError('Metadati avvio non validi')
        if state['had_main']:
            if not _exists(backup) or _hash(backup)!=state['backup_sha256']:raise ValueError('Backup main assente o non valido')
            _copy(backup,main+'.new');_replace(main+'.new',main)
        else:os.remove(main)
        previous=state.get('boot_option');_set(nvs,previous if type(previous)==int and previous in (0,1,2) else 1)
        os.remove(state_path)
        # Backup is deliberately kept for review; never deletes user startup code.
    elif action!='read':raise ValueError('Operazione avvio non valida')
    return {'boot_option':_mode(nvs),'main_exists':_exists(main),'main_owned':_owned(main),
            'app_exists':_exists(app),'restore_available':_exists(state_path),
            'pending_uiflow_ota':_exists(BASE+'/main_ota_temp.py'),
            'recovery':'Hold B while powering on; select UIFlow menu on next boot'}
